{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Secure transfer is disabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The storage account explicitly allows non-HTTPS traffic, which can expose media data and credentials to interception in transit."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Legacy TLS version is permitted",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The minimum TLS version is TLS 1.0, which is deprecated and vulnerable to known cryptographic weaknesses."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                      = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name       = azurerm_resource_group.corporate_media_streaming.name\n  location                  = azurerm_resource_group.corporate_media_streaming.location\n  account_tier              = \"Standard\"\n  account_replication_type  = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version           = \"TLS1_2\"\n\n  blob_properties {\n    versioning_enabled = true\n  }\n}\n",
  "fix_summary": "Enabled HTTPS-only traffic and raised the storage account's minimum supported TLS version from TLS 1.0 to TLS 1.2."
}
